insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPYDTZYSYQJXZSJQTYNZXQ', '02', 'SQL', 'SELECT NVL(NVL(plans.exercise_date, A.MDATE) - DATE''${valDate}''-1, 0) AS RVALUE, a.finprod_id AS rkey 
  FROM FIN_PRODUCT A
  LEFT JOIN (SELECT NVL(MIN(a.exercise_date),NULL) AS exercise_date,a.finprod_id FROM FIN_EXERCISE_PLAN a WHERE a.EXERCISE_STATUS<>''02'' 
AND a.exercise_date>DATE''${valDate}'' AND a.exercise_type=''01'' GROUP BY a.finprod_id) plans
ON plans.finprod_id = a.finprod_id 
 WHERE A.FINPROD_TYPE2 = ''F01''
   AND A.TRADE_MARKET IN (''01'', ''03'', ''04'')', 'assetCode', 'N', 'admin', '001', '21-9月 -20 09.01.58.026000 下午', 'admin', '21-9月 -20 09.01.58.240000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPYDTZYSYQJXZSJQTYNZXQ', '03', 'SQL', 'SELECT NVL(NVL(plans.exercise_date, A.MDATE) - DATE''${valDate}''-1, 0) AS RVALUE, a.finprod_id AS rkey 
  FROM FIN_PRODUCT A
  LEFT JOIN (SELECT NVL(MIN(a.exercise_date),NULL) AS exercise_date,a.finprod_id FROM FIN_EXERCISE_PLAN a WHERE a.EXERCISE_STATUS<>''02'' 
AND a.exercise_date>DATE''${valDate}'' AND a.exercise_type=''01'' GROUP BY a.finprod_id) plans
ON plans.finprod_id = a.finprod_id 
 WHERE A.FINPROD_TYPE2 = ''F01''
   AND A.TRADE_MARKET IN (''01'', ''03'', ''04'')', 'assetCode', 'N', 'admin', '001', '21-9月 -20 09.01.58.026000 下午', 'admin', '21-9月 -20 09.01.58.242000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPYDTZYSYQJXZSJQTYNZXQ', '01', 'SQL', 'SELECT NVL(NVL(plans.exercise_date, A.MDATE) - DATE''${valDate}''-1, 0) AS RVALUE, a.finprod_id AS rkey 
  FROM FIN_PRODUCT A
  LEFT JOIN (SELECT NVL(MIN(a.exercise_date),NULL) AS exercise_date,a.finprod_id FROM FIN_EXERCISE_PLAN a WHERE a.EXERCISE_STATUS<>''02'' 
AND a.exercise_date>DATE''${valDate}'' AND a.exercise_type=''01'' GROUP BY a.finprod_id) plans
ON plans.finprod_id = a.finprod_id 
 WHERE A.FINPROD_TYPE2 = ''F01''
   AND A.TRADE_MARKET IN (''01'', ''03'', ''04'')', 'assetCode', 'N', 'admin', '001', '21-9月 -20 09.01.58.026000 下午', 'admin', '21-9月 -20 09.01.58.243000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CPJZCGZ', '03', 'SQL', 'WITH  temp  as(
  SELECT
       DISTINCT t2.PORTFOLIO_ID ,
       mujiData.mujiAmt  as AMOUNT
       from  PTL_PORTFOLIO t2
       left join
       (
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1
       WHERE  t1.PS in (''C1'', ''C2'')  and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''
       group by t1.PORTFOLIO_ID
       ) mujiData
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID
       where  t2.VDATE=date''${valDate}''
 UNION ALL
      SELECT
       DISTINCT t1.PORTFOLIO_ID RKEY,
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE
       from PTL_PORTFOLIO_VALUATION t1
       where  t1.CDATE=date''${valDate}''-1
 )
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp
union all
   select m.PTL_BAG_ID as RKEY,
   (
        SELECT sum(AMOUNT) FROM (
          SELECT PORTFOLIO_ID,AMOUNT FROM temp
       ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1
       inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)
   ) AS RVALUE
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'admin', '001', '14-9月 -20 07.14.02.606000 下午', 'admin', '14-9月 -20 07.14.02.836000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CPJZCGZ', '01', 'SQL', 'WITH  temp  as(
  SELECT
       DISTINCT t2.PORTFOLIO_ID ,
       mujiData.mujiAmt  as AMOUNT
       from  PTL_PORTFOLIO t2
       left join
       (
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1
       WHERE  t1.PS in (''C1'', ''C2'')  and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''
       group by t1.PORTFOLIO_ID
       ) mujiData
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID
       where  t2.VDATE=date''${valDate}''
 UNION ALL
      SELECT
       DISTINCT t1.PORTFOLIO_ID RKEY,
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE
       from PTL_PORTFOLIO_VALUATION t1
       where  t1.CDATE=date''${valDate}''-1
 )
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp
union all
   select m.PTL_BAG_ID as RKEY,
   (
        SELECT sum(AMOUNT) FROM (
          SELECT PORTFOLIO_ID,AMOUNT FROM temp
       ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1
       inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)
   ) AS RVALUE
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'admin', '001', '14-9月 -20 07.14.02.606000 下午', 'admin', '14-9月 -20 07.14.02.838000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('TZYZTXYPJDYAAATYSYYH', '02', 'SQL', 'SELECT
    SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE,
    VAL.PORTFOLIO_ID ||'',''|| PRD.ISSUER RKEY
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = VAL.FINPROD_ID AND (TYP.TYPE_8 = ''F05'' OR
(TYP.TYPE_8 = ''F01'' AND TYP.TYPE_6 = ''B04''))
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT =''02'' GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
WHERE VAL.CDATE = date''${valDate}'' - 1
GROUP BY VAL.PORTFOLIO_ID,PRD.ISSUER', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 09.58.19.643000 上午', 'admin', '16-9月 -20 09.58.19.862000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('TZYDYZTXYPJDYAAAJGHJ', '01', 'SQL', 'SELECT
SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE,
    VAL.PORTFOLIO_ID || '','' || PRD.ISSUER RKEY
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'')
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT NOT IN (''01'',''02'') GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
 WHERE VAL.CDATE = date''${valDate}'' - 1
GROUP BY VAL.PORTFOLIO_ID,PRD.ISSUER', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 09.34.05.569000 上午', 'admin', '16-9月 -20 09.34.05.919000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CKHGYPTYSYQX', '05', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,MDATE,NULL FINPROD_NAME FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION ALL
    -- 活期存款
    SELECT FP.FINPROD_ID,DATE''${valDate}'' MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 = ''D03''
  UNION ALL
    -- 非活期存款
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 != ''D03''
  UNION ALL
    -- 央票、同业存单（非含权）
    SELECT FP.FINPROD_ID,NVL(FXZ.MDATE,FP.MDATE) MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'') AND FP.IS_RIGHT = ''N'' ', 'assetCode', 'N', 'admin', '001', '11-9月 -20 04.40.17.939000 下午', 'admin', '11-9月 -20 04.40.18.207000 下午');
  ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION ALL
    -- 央票、同业存单（含权）
    SELECT FP.FINPROD_ID,
    CASE WHEN NVL(FXZ.MDATE, t1.MDATE) < t1.MDATE THEN NVL(FXZ.MDATE,FP.MDATE) ELSE NVL(t1.MDATE,FP.MDATE) END MDATE,FP.FINPROD_NAME
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    AND FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'')
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT RKEY, RVALUE, RKEYCN FROM (
SELECT SUM(NVL(SHARE_AMT,0)) SHARE_AMT, FINPROD_ID RKEY, TO_NUMBER(MDATE - DATE ''${valDate}'') RVALUE, FINPROD_NAME RKEYCN FROM (
    SELECT SUM(NVL(PSP.AMOUNT,0)) SHARE_AMT, PSP.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
    FROM PTL_SEC_POSITION PSP
    INNER JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = PSP.FINPROD_ID
    INNER JOIN ASSET ON ASSET.FINPROD_ID = FP.FINPROD_ID
    WHERE PSP.CDATE = DATE ''${valDate}'' - 1 AND PSP.PORTFOLIO_ID IN ${portfolioCode}
    GROUP BY PSP.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.SHARE_AMT*-1, n.SHARE_AMT))), 0) AS SHARE_AMT,
        n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
    FROM TRD_PRODUCT_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = n.FINPROD_ID
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE n.TRADE_DATE = DATE''${valDate}'' AND m.PORTFOLIO_ID IN ${portfolioCode}
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T39'', ''T39'')
    GROUP BY n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME' where PARA_CODE = 'CKHGYPTYSYQX' and PARA_GRANULARITY='05';
  ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)  AS TRADE_AMT,
      n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = n.FINPROD_ID
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T52'')
    GROUP BY n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN FIN_PRODUCT FP ON FP.FINPROD_ID = n.FINPROD_ID
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE n.counter_id IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS =''T02''
    AND EXISTS (SELECT 1 FROM SYS_PARA WHERE PARA_CODE = ''is_auto_generate_negate_deal'' AND PARAM_VALUE = ''Y'')
    GROUP BY n.FINPROD_ID, ASSET.MDATE, ASSET.FINPROD_NAME
) GROUP BY FINPROD_ID, MDATE,FINPROD_NAME
) WHERE SHARE_AMT > 0' where PARA_CODE = 'CKHGYPTYSYQX' and PARA_GRANULARITY='05';

