values ('GZZYYXHPJHZCXJRZXQGZ', '02', 'SQL', 'SELECT NVL(SUM(A.MARKET_VALUE), 0) AS RVALUE,A.PORTFOLIO_ID AS RKEY 
  FROM PTL_SEC_PIERCE_VALUTION A
