                          FROM FIN_PRODUCT T1
                          LEFT JOIN FIN_PRODUCT_TYPE T4
                            ON T4.FINPROD_ID = T1.FINPROD_ID
                         WHERE T1.FINPROD_TYPE2 = ''F01''
                           AND T4.TYPE_10 IN (''03'', ''04'', ''05'', ''06''))
                           GROUP BY A.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '31-8月 -20 05.35.16.586000 上午', 'admin', '31-8月 -20 05.35.16.779000 上午');

