                           GROUP BY A.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '31-8月 -20 05.35.16.586000 上午', 'admin', '31-8月 -20 05.35.16.780000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('TZYSYZTXYPJDYAAAJGHJ', '05', 'SQL', 'SELECT
    SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'')
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT NOT IN (''01'',''02'') GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
WHERE VAL.CDATE = date''${valDate}''   AND VAL.PORTFOLIO_ID IN ${portfolioCode}', 'portfolioCode', 'N', 'admin', '001', '16-9月 -20 06.19.15.653000 下午', 'admin', '16-9月 -20 06.19.15.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LDXSXZCGZ', '02', 'SQL', 'WITH PROD AS (
    -- 资产到期向前第10个交易日
    SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_TYPE2, m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_TYPE2,FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.FINPROD_TYPE2 IN (''F01'', ''F07'') AND FPT.MDATE >= DATE ''${valDate}'' - 1
                UNION ALL
                SELECT FTP.FINPROD_TYPE2,FTP.FINPROD_ID,FTP.MDATE,NVL(FTP.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_TRADE_PRODUCT FTP
                WHERE FTP.MDATE IS NOT NULL AND FTP.FINPROD_TYPE2 IN (''F03'',''F05'') AND FTP.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 10
    ) WHERE RN = 1
)
SELECT
    NVL(SUM(NVL(m.DSC_COST_AMT,0)+nvl(m.TDY_INTINCEXP, 0)),0) RVALUE,
    M.PORTFOLIO_ID RKEY
FROM PTL_SEC_PIERCE_VALUTION M
INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID AND N.CDATE > DATE ''${valDate}'' - 1
WHERE M.CDATE = date''${valDate}'' - 1
GROUP BY M.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '15-9月 -20 11.13.36.369000 上午', 'admin', '15-9月 -20 11.13.36.611000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LDXSXZCGZ', '04', 'SQL', 'WITH PROD AS (
    -- 资产到期向前第10个交易日
    SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_TYPE2, m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_TYPE2,FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.FINPROD_TYPE2 IN (''F01'', ''F07'') AND FPT.MDATE >= DATE ''${valDate}'' - 1
                UNION ALL
                SELECT FTP.FINPROD_TYPE2,FTP.FINPROD_ID,FTP.MDATE,NVL(FTP.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_TRADE_PRODUCT FTP
                WHERE FTP.MDATE IS NOT NULL AND FTP.FINPROD_TYPE2 IN (''F03'',''F05'') AND FTP.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 10
    ) WHERE RN = 1
)
SELECT SUM(TRADE_AMT) RVALUE FROM (
    SELECT
        NVL(SUM(NVL(M.DSC_COST_AMT ,0)),0) TRADE_AMT
    FROM PTL_SEC_PIERCE_VALUTION M
    INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID AND N.CDATE > DATE ''${valDate}'' - 1
    WHERE M.CDATE = date''${valDate}'' - 1 AND  M.PORTFOLIO_ID IN ${portfolioCode} ', 'portfolioCode', 'N', 'admin', '001', '15-9月 -20 11.13.36.369000 上午', 'admin', '15-9月 -20 11.13.36.620000 上午');
   ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT
    FROM TRD_PRODUCT_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.CDATE > DATE ''${valDate}'' - 1
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T39'', ''T38'')
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.CDATE > DATE ''${valDate}'' - 1
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T52'')
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID AND t2.CDATE > DATE ''${valDate}'' - 1
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    WHERE n.counter_id IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND n.PS = ''T02''
    AND EXISTS (SELECT 1 FROM SYS_PARA WHERE PARA_CODE = ''is_auto_generate_negate_deal'' AND PARAM_VALUE = ''Y'')
)'  where PARA_CODE = 'LDXSXZCGZ' and PARA_GRANULARITY='04';

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LDXSXZCGZ', '05', 'SQL', 'WITH PROD AS (
    -- 资产到期向前第10个交易日
    SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_TYPE2, m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_TYPE2,FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.FINPROD_TYPE2 IN (''F01'', ''F07'') AND FPT.MDATE >= DATE ''${valDate}'' - 1
                UNION ALL
                SELECT FTP.FINPROD_TYPE2,FTP.FINPROD_ID,FTP.MDATE,NVL(FTP.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_TRADE_PRODUCT FTP
                WHERE FTP.MDATE IS NOT NULL AND FTP.FINPROD_TYPE2 IN (''F03'',''F05'') AND FTP.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 10
    ) WHERE RN = 1
)
SELECT SUM(TRADE_AMT) RVALUE FROM (
    SELECT
        NVL(SUM(NVL(M.DSC_COST_AMT ,0)),0) TRADE_AMT
    FROM PTL_SEC_PIERCE_VALUTION M
    INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID AND N.CDATE > DATE ''${valDate}'' - 1
    WHERE M.CDATE = date''${valDate}'' - 1 AND  M.PORTFOLIO_ID IN ${portfolioCode} ', 'portfolioCode', 'N', 'admin', '001', '15-9月 -20 11.13.36.369000 上午', 'admin', '15-9月 -20 11.13.36.625000 上午');
