insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CPJZCGZ', '02', 'SQL', 'WITH  temp  as(
  SELECT
       DISTINCT t2.PORTFOLIO_ID ,
       mujiData.mujiAmt  as AMOUNT
       from  PTL_PORTFOLIO t2
       left join
       (
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1
       WHERE  t1.PS in (''C1'', ''C2'')  and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''
       group by t1.PORTFOLIO_ID
       ) mujiData
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID
       where  t2.VDATE=date''${valDate}''
 UNION ALL
      SELECT
       DISTINCT t1.PORTFOLIO_ID RKEY,
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE
       from PTL_PORTFOLIO_VALUATION t1
       where  t1.CDATE=date''${valDate}''-1
 )
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp
union all
   select m.PTL_BAG_ID as RKEY,
   (
        SELECT sum(AMOUNT) FROM (
          SELECT PORTFOLIO_ID,AMOUNT FROM temp
       ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1
       inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)
   ) AS RVALUE
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'admin', '001', '14-9月 -20 07.14.02.606000 下午', 'admin', '14-9月 -20 07.14.02.833000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('SGJYRLJSHZ', '02', 'SQL', 'SELECT prod.finprod_market_id rkey,NVL(SUM(A.TRADE_AMT), 0) RVALUE
               FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
               INNER JOIN fin_product prod ON prod.finprod_id=a.finprod_id AND prod.finprod_type2=''F16''
              WHERE A.FINPROD_TYPE2 = ''F16''
                AND A.PS = ''C4''
                AND A.TRADE_DATE <= SYSDATE
                AND A.IS_CANCEL = DECODE(''01'', ''03'', ''Y'', ''N'')
                AND A.TRADE_DATE IN
                    ((SELECT MAX(A.CDATE)
                       FROM MST_HOLIDAY A
                      WHERE A.IS_HOLIDAY = ''0''
                        AND A.CALENDAR_ID = ''01''
                        AND A.CDATE <= date''${valDate}''),
                     (SELECT MAX(A.CDATE)
                        FROM MST_HOLIDAY A
                       WHERE A.IS_HOLIDAY = ''0''
                         AND A.CALENDAR_ID = ''01''
                         AND A.CDATE < (SELECT MAX(A.CDATE)
                                          FROM MST_HOLIDAY A
                                         WHERE A.IS_HOLIDAY = ''0''
                                           AND A.CALENDAR_ID = ''01''
                                           AND A.CDATE <= date''${valDate}'')),
                     (SELECT MAX(A.CDATE)
                        FROM MST_HOLIDAY A
                       WHERE A.IS_HOLIDAY = ''0''
                         AND A.CALENDAR_ID = ''01''
                         AND A.CDATE <
                             (SELECT MAX(A.CDATE)
                                FROM MST_HOLIDAY A
                               WHERE A.IS_HOLIDAY = ''0''
                                 AND A.CALENDAR_ID = ''01''
                                 AND A.CDATE < (SELECT MAX(A.CDATE)
                                                  FROM MST_HOLIDAY A
                                                 WHERE A.IS_HOLIDAY = ''0''
                                                   AND A.CALENDAR_ID = ''01''
                                                   AND A.CDATE <= date''${valDate}''))))
                                                   GROUP BY prod.finprod_market_id', 'portfolioCode', 'N', 'admin', '001', '09-9月 -20 11.04.08.880000 上午', 'admin', '09-9月 -20 11.04.09.126000 上午');

