insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('SGJYRLJSHZ', '05', 'SQL', 'SELECT NVL(SUM(A.TRADE_AMT), 0) RVALUE
               FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
               INNER JOIN fin_product prod ON prod.finprod_id=a.finprod_id AND prod.finprod_type2=''F16''
              WHERE A.FINPROD_TYPE2 = ''F16''
                AND a.finprod_id IN (SELECT prod.finprod_id FROM fin_product prod WHERE prod.finprod_market_id IN (${portfolioCode}))
                AND A.PS = ''C4''
                AND A.TRADE_DATE <= SYSDATE
                AND A.IS_CANCEL = DECODE(''01'', ''03'', ''Y'', ''N'')
                AND A.TRADE_DATE IN
                    ((SELECT MAX(A.CDATE)
                       FROM MST_HOLIDAY A
                      WHERE A.IS_HOLIDAY = ''0''
                        AND A.CALENDAR_ID = ''01''
                        AND A.CDATE <= date''${valDate}''),
                     (SELECT MAX(A.CDATE)
                        FROM MST_HOLIDAY A
                       WHERE A.IS_HOLIDAY = ''0''
                         AND A.CALENDAR_ID = ''01''
                         AND A.CDATE < (SELECT MAX(A.CDATE)
                                          FROM MST_HOLIDAY A
                                         WHERE A.IS_HOLIDAY = ''0''
                                           AND A.CALENDAR_ID = ''01''
                                           AND A.CDATE <= date''${valDate}'')),
                     (SELECT MAX(A.CDATE)
                        FROM MST_HOLIDAY A
                       WHERE A.IS_HOLIDAY = ''0''
                         AND A.CALENDAR_ID = ''01''
                         AND A.CDATE <
                             (SELECT MAX(A.CDATE)
                                FROM MST_HOLIDAY A
                               WHERE A.IS_HOLIDAY = ''0''
                                 AND A.CALENDAR_ID = ''01''
                                 AND A.CDATE < (SELECT MAX(A.CDATE)
                                                  FROM MST_HOLIDAY A
                                                 WHERE A.IS_HOLIDAY = ''0''
                                                   AND A.CALENDAR_ID = ''01''
                                                   AND A.CDATE <= date''${valDate}''))))', 'portfolioCode', 'N', 'admin', '001', '09-9月 -20 11.04.08.880000 上午', 'admin', '09-9月 -20 11.04.09.143000 上午');

