insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XYDJZAAYXDZQ', '02', 'SQL', 'select * from
(
SELECT D.finprod_id AS RKEY,A.GRADE_RESULT || ''||'' || C.ITEM_VALUE AS RVALUE
 from MST_BOND_CREDIT_RATING A JOIN
(select O_CODE,max(GRADE_DATE) GRADE_DATE
from MST_BOND_CREDIT_RATING  where O_TYPE = ''01'' GROUP BY O_CODE) B
ON A.O_CODE = B.O_CODE AND A.GRADE_DATE = B.GRADE_DATE AND A.O_TYPE = ''01''
LEFT JOIN FIN_PRODUCT D ON D.finprod_market_id = A.o_code
JOIN
SYS_DATADICT_LIST C ON C.DICT_CODE=''MAIN_GRADE_RESULT'' and A.GRADE_RESULT = C.ITEM_CODE
WHERE D.finprod_id not in (select B.FINPROD_ID from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_11
 where B.TYPE_11 IN  (''011'',''013'') AND C.dict_code = ''CUSTOM_ASSET_TYPE_FOUR''
UNION ALL
select B.FINPROD_ID from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_8
 where B.TYPE_8 IN  (''F10'') AND C.dict_code = ''FINPROD_TYPE''
UNION ALL
select T1.FINPROD_ID from FIN_PRODUCT T1
LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID
AND T3.EFF_DATE = T1.VDATE WHERE T3.INT_TYPE = ''02''
)

UNION ALL

select B.FINPROD_ID RKEY,B.TYPE_11 || ''||'' || C.ITEM_VALUE RVALUE from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_11
 where B.TYPE_11 IN  (''011'',''013'') AND C.dict_code = ''CUSTOM_ASSET_TYPE_FOUR''
UNION ALL
select B.FINPROD_ID RKEY, B.TYPE_8 || ''||'' || C.ITEM_VALUE RVALUE from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_8
 where B.TYPE_8 IN  (''F10'') AND C.dict_code = ''FINPROD_TYPE''
UNION ALL
select T1.FINPROD_ID RKEY , ''fd02'' || ''||'' || ''浮动利率债券'' RVALUE from FIN_PRODUCT T1
LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID
AND T3.EFF_DATE = T1.VDATE WHERE T3.INT_TYPE = ''02'')', 'assetCode', 'N', 'admin', '001', '17-9月 -20 11.23.16.970000 上午', 'admin', '17-9月 -20 11.23.17.201000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPYDTZYSYQJXZSJQTYNZXQ', '04', 'SQL', 'WITH ASSET AS (
    -- 剔除央票、同业存单 债券（非含权）
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID 
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND (FPT.type_6 NOT IN (''B03'',''B04'',''B13'') 
    OR (FPT.type_6 = ''B13'' AND FP.TRADE_MARKET IN (''01'',''03'',''04'')))
    AND FP.IS_RIGHT = ''N''
  UNION ALL
    -- 剔除央票、同业存单 债券（含权）
    SELECT FP.FINPROD_ID,t1.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP 
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID 
    AND FP.FINPROD_TYPE2 = ''F01'' AND (FPT.type_6 NOT IN (''B03'',''B04'',''B13'') 
    OR (FPT.type_6 = ''B13'' AND FP.TRADE_MARKET IN (''01'',''03'',''04'')))
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT distinct TO_NUMBER(ASSET.MDATE - DATE ''${valDate}''-1) RVALUE, ASSET.FINPROD_ID RKEY, ASSET.FINPROD_NAME RKEYCN
FROM PTL_SEC_POSITION PSP
INNER JOIN ASSET ON ASSET.FINPROD_ID = PSP.FINPROD_ID 
WHERE ASSET.MDATE > DATE ''${valDate}''
AND PSP.PORTFOLIO_ID IN ${portfolioCode} AND PSP.CDATE = DATE ''${valDate}''', 'assetCode', 'N', 'admin', '001', '21-9月 -20 09.01.58.026000 下午', 'admin', '21-9月 -20 09.01.58.244000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPYDTZYSYQJXZSJQTYNZXQ', '05', 'SQL', 'WITH ASSET AS (
    -- 剔除央票、同业存单 债券（非含权）
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID 
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND (FPT.type_6 NOT IN (''B03'',''B04'',''B13'') 
    OR (FPT.type_6 = ''B13'' AND FP.TRADE_MARKET IN (''01'',''03'',''04'')))
    AND FP.IS_RIGHT = ''N''
  UNION ALL
    -- 剔除央票、同业存单 债券（含权）
    SELECT FP.FINPROD_ID,t1.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP 
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID 
    AND FP.FINPROD_TYPE2 = ''F01'' AND (FPT.type_6 NOT IN (''B03'',''B04'',''B13'') 
    OR (FPT.type_6 = ''B13'' AND FP.TRADE_MARKET IN (''01'',''03'',''04'')))
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT distinct TO_NUMBER(ASSET.MDATE - DATE ''${valDate}''-1) RVALUE, ASSET.FINPROD_ID RKEY, ASSET.FINPROD_NAME RKEYCN
FROM PTL_SEC_POSITION PSP
INNER JOIN ASSET ON ASSET.FINPROD_ID = PSP.FINPROD_ID 
WHERE ASSET.MDATE > DATE ''${valDate}''
AND PSP.PORTFOLIO_ID IN ${portfolioCode} AND PSP.CDATE = DATE ''${valDate}''', 'assetCode', 'N', 'admin', '001', '21-9月 -20 09.01.58.026000 下午', 'admin', '21-9月 -20 09.01.58.246000 下午');

