INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = VAL.FINPROD_ID
AND (TYP.TYPE_8 = ''F05'' OR (TYP.TYPE_8 = ''F01'' AND TYP.TYPE_6 = ''B04''))
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT = ''02'' GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
WHERE VAL.CDATE = date''${valDate}'' AND VAL.PORTFOLIO_ID IN ${portfolioCode}
GROUP BY PRD.ISSUER', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 06.19.15.653000 下午', 'admin', '16-9月 -20 06.19.15.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LDXSXZCGZ', '01', 'SQL', 'WITH PROD AS (
    -- 资产到期向前第10个交易日
    SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_TYPE2, m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_TYPE2,FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.FINPROD_TYPE2 IN (''F01'', ''F07'') AND FPT.MDATE >= DATE ''${valDate}'' - 1
                UNION ALL
                SELECT FTP.FINPROD_TYPE2,FTP.FINPROD_ID,FTP.MDATE,NVL(FTP.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_TRADE_PRODUCT FTP
                WHERE FTP.MDATE IS NOT NULL AND FTP.FINPROD_TYPE2 IN (''F03'',''F05'') AND FTP.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 10
    ) WHERE RN = 1
)
SELECT
    NVL(SUM(NVL(m.DSC_COST_AMT,0)+nvl(m.TDY_INTINCEXP, 0)),0) RVALUE,
    M.PORTFOLIO_ID RKEY
FROM PTL_SEC_PIERCE_VALUTION M
INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID AND N.CDATE > DATE ''${valDate}'' - 1
WHERE M.CDATE = date''${valDate}'' - 1
GROUP BY M.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '15-9月 -20 11.13.36.369000 上午', 'admin', '15-9月 -20 11.13.36.617000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CKHGYPTYSYQX', '02', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,MDATE,NULL FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION ALL
    -- 活期存款
    SELECT FP.FINPROD_ID,DATE''${valDate}'' MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 = ''D03''
  UNION ALL
    -- 非活期存款
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 != ''D03''
  UNION ALL
    -- 央票、同业存单（非含权）
    SELECT FP.FINPROD_ID,NVL(FXZ.MDATE,FP.MDATE) MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'') AND FP.IS_RIGHT = ''N''
  UNION ALL
    -- 央票、同业存单（含权）
    SELECT FP.FINPROD_ID,
    CASE WHEN NVL(FXZ.MDATE, t1.MDATE) < t1.MDATE THEN NVL(FXZ.MDATE,FP.MDATE) ELSE NVL(t1.MDATE,FP.MDATE) END MDATE,FP.FINPROD_NAME
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    AND FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'')
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT TO_NUMBER(ASSET.MDATE - DATE ''${valDate}'' - 1) RVALUE, ASSET.FINPROD_ID RKEY
FROM ASSET WHERE ASSET.MDATE > DATE ''${valDate}''', 'assetCode', 'N', 'admin', '001', '11-9月 -20 04.40.17.939000 下午', 'admin', '11-9月 -20 04.40.18.192000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CKHGYPTYSYQX', '03', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,MDATE,NULL FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION ALL
    -- 活期存款
    SELECT FP.FINPROD_ID,DATE''${valDate}'' MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 = ''D03''
  UNION ALL
    -- 非活期存款
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 != ''D03''
  UNION ALL
    -- 央票、同业存单（非含权）
    SELECT FP.FINPROD_ID,NVL(FXZ.MDATE,FP.MDATE) MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'') AND FP.IS_RIGHT = ''N''
  UNION ALL
    -- 央票、同业存单（含权）
    SELECT FP.FINPROD_ID,
    CASE WHEN NVL(FXZ.MDATE, t1.MDATE) < t1.MDATE THEN NVL(FXZ.MDATE,FP.MDATE) ELSE NVL(t1.MDATE,FP.MDATE) END MDATE,FP.FINPROD_NAME
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    AND FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'')
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT TO_NUMBER(ASSET.MDATE - DATE ''${valDate}'' - 1) RVALUE, ASSET.FINPROD_ID RKEY
FROM ASSET WHERE ASSET.MDATE > DATE ''${valDate}''', 'assetCode', 'N', 'admin', '001', '11-9月 -20 04.40.17.939000 下午', 'admin', '11-9月 -20 04.40.18.196000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('CKHGYPTYSYQX', '01', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,MDATE,NULL FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION ALL
    -- 活期存款
    SELECT FP.FINPROD_ID,DATE''${valDate}'' MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 = ''D03''
  UNION ALL
    -- 非活期存款
    SELECT FP.FINPROD_ID,FP.MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F07'' AND FPT.TYPE_6 != ''D03''
  UNION ALL
    -- 央票、同业存单（非含权）
    SELECT FP.FINPROD_ID,NVL(FXZ.MDATE,FP.MDATE) MDATE,FP.FINPROD_NAME FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'') AND FP.IS_RIGHT = ''N''
  UNION ALL
    -- 央票、同业存单（含权）
    SELECT FP.FINPROD_ID,
    CASE WHEN NVL(FXZ.MDATE, t1.MDATE) < t1.MDATE THEN NVL(FXZ.MDATE,FP.MDATE) ELSE NVL(t1.MDATE,FP.MDATE) END MDATE,FP.FINPROD_NAME
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    AND FP.FINPROD_TYPE2 = ''F01'' AND FPT.type_6 IN (''B03'',''B04'')
    LEFT JOIN (
        SELECT FCP.FINPROD_ID,FCP.MDATE FROM FIN_CASH_PLAN FCP
        WHERE FCP.FINPROD_TYPE2 = ''F01'' AND FCP.CASH_TYPE = ''04'' AND FCP.CASH_ID IN (
            SELECT FCI.CASH_ID FROM FIN_CASH_INFO FCI
            INNER JOIN FIN_CASH_CALC_RULE FCC ON FCC.CASH_ID = FCI.CASH_ID AND FCC.CALC_TYPE = ''02''
            WHERE FCI.CASH_TYPE_1 = ''02''
        )
    ) FXZ ON FXZ.FINPROD_ID = FP.FINPROD_ID
    LEFT JOIN (
        SELECT FINPROD_ID,min(EXERCISE_DATE) MDATE FROM FIN_EXERCISE_PLAN
        WHERE EXERCISE_DATE >= DATE ''${valDate}''
        GROUP BY FINPROD_ID
    ) t1 ON t1.FINPROD_ID = FP.FINPROD_ID
    WHERE FP.IS_RIGHT = ''Y''
)
SELECT TO_NUMBER(ASSET.MDATE - DATE ''${valDate}'' - 1) RVALUE, ASSET.FINPROD_ID RKEY
FROM ASSET WHERE ASSET.MDATE > DATE ''${valDate}''', 'assetCode', 'N', 'admin', '001', '11-9月 -20 04.40.17.939000 下午', 'admin', '11-9月 -20 04.40.18.199000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('TZYSYZTXYPJDYAAAJGHJ', '04', 'SQL', 'SELECT
    SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'')
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT NOT IN (''01'',''02'') GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
WHERE VAL.CDATE = date''${valDate}''   AND VAL.PORTFOLIO_ID IN ${portfolioCode}', 'portfolioCode', 'N', 'admin', '001', '16-9月 -20 09.34.22.626000 上午', 'admin', '16-9月 -20 09.34.22.859000 上午');

