LEFT JOIN MST_CUSTOMER_INFO CST ON PRD.ISSUER = CST.CUSTOMER_ID
WHERE VAL.CDATE = date''${valDate}'' AND VAL.PORTFOLIO_ID IN ${portfolioCode}
GROUP BY PRD.ISSUER,CST.CUSTOMER_NAME', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 06.19.15.653000 下午', 'admin', '16-9月 -20 06.19.15.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('GZZYYXHPJHZCXJRZXQGZ', '01', 'SQL', 'SELECT NVL(SUM(A.MARKET_VALUE), 0) AS RVALUE,A.PORTFOLIO_ID AS RKEY 
  FROM PTL_SEC_PIERCE_VALUTION A
 WHERE A.CDATE = date''${valDate}''
   AND A.FINPROD_ID IN (SELECT T1.FINPROD_ID
                          FROM FIN_PRODUCT T1
                          LEFT JOIN FIN_PRODUCT_TYPE T4
                            ON T4.FINPROD_ID = T1.FINPROD_ID
                         WHERE T1.FINPROD_TYPE2 = ''F01''
                           AND T4.TYPE_10 IN (''03'', ''04'', ''05'', ''06''))
                           GROUP BY A.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '31-8月 -20 05.35.16.586000 上午', 'admin', '31-8月 -20 05.35.16.781000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('LDXSXZCGZ', '03', 'SQL', 'WITH PROD AS (
    -- 资产到期向前第10个交易日
    SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_TYPE2, FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_TYPE2, m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_TYPE2,FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.FINPROD_TYPE2 IN (''F01'', ''F07'') AND FPT.MDATE >= DATE ''${valDate}'' - 1
                UNION ALL
                SELECT FTP.FINPROD_TYPE2,FTP.FINPROD_ID,FTP.MDATE,NVL(FTP.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_TRADE_PRODUCT FTP
                WHERE FTP.MDATE IS NOT NULL AND FTP.FINPROD_TYPE2 IN (''F03'',''F05'') AND FTP.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 10
    ) WHERE RN = 1
)
SELECT
    NVL(SUM(NVL(m.DSC_COST_AMT,0)+nvl(m.TDY_INTINCEXP, 0)),0) RVALUE,
    M.PORTFOLIO_ID RKEY
FROM PTL_SEC_PIERCE_VALUTION M
INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID AND N.CDATE > DATE ''${valDate}'' - 1
WHERE M.CDATE = date''${valDate}'' - 1
GROUP BY M.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '15-9月 -20 11.13.36.369000 上午', 'admin', '15-9月 -20 11.13.36.614000 上午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('TYJGFXDZQJQZWYSQYRDZCZCZQGZHJ', '05', 'SQL', 'SELECT
    SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE, PRD.ISSUER RKEY, CST.CUSTOMER_NAME RKEYCN
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID AND PRD.FINPROD_TYPE2 = ''F01''
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND (TYP.TYPE_6 NOT IN (''B01'',''B03'',''B17'',''B05'')
OR (TYP.TYPE_6 = ''B05'' AND TYP.TYPE_7 != ''01'')) AND TYP.TYPE_8 = ''F01''
LEFT JOIN MST_CUSTOMER_INFO CST ON CST.CUSTOMER_ID = PRD.ISSUER
WHERE VAL.CDATE = date''${valDate}''  AND VAL.PORTFOLIO_ID IN ${portfolioCode}
GROUP BY PRD.ISSUER,CST.CUSTOMER_NAME', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 06.19.15.653000 下午', 'admin', '16-9月 -20 06.19.15.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('YGDQXYHCKGZ', '03', 'SQL', 'SELECT nvl(SUM(rvalue),0) AS rvalue ,rkey  FROM (
SELECT PP.PORTFOLIO_ID  AS rkey ,
       nvl(SUM(DECODE(wfl.ps,''T01'',WFL.PRIN_AMT,''T02'',WFL.PRIN_AMT*-1,WFL.PRIN_AMT)),0)  AS rvalue
  FROM TRD_PRODUCT_DEAL WFL
  LEFT JOIN PTL_TRADE PT
    ON NVL(WFL.P_TRADE_ID, WFL.TRADE_ID) = PT.BUSI_NO
  LEFT JOIN PTL_PORTFOLIO PP
    ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
 WHERE PP.INVEST_YESORNO = ''Y''
   AND WFL.FINPROD_TYPE2 = ''F07''
   AND wfl.trade_date = date''${valDate}''
   AND WFL.PS IN (''T01'', ''T02'')
   AND WFL.TRADE_STATUS = ''01''
   AND WFL.IS_CANCEL != ''Y''
   AND pp.mdate>=date''${valDate}''
   GROUP BY pp.portfolio_id
UNION ALL 
SELECT  replace(a.bookset_id,''F16_'','''') AS rkey,A.MARKET_VALUE  AS rvalue /**原币估值**/
  FROM BOK_VAL_TABLE_DATA A
 WHERE A.VAL_DATE = date''${valDate}''-1
   AND A.DETAIL_DIST = ''01''
   AND DECODE(A.FSUBJECT_ID,
              NULL,
              ''root'',
              DECODE(A.FSUBJECT_ID, '' '', ''root'', A.FSUBJECT_ID)) = ''1003''
UNION ALL
SELECT t1.portfolio_id AS rkey,NVL(SUM(T1.FPRICE_AMT)*-1,0) AS rvalue
                        
                   FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
                   LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3  ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID
                   LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID
                   LEFT JOIN FIN_PRODUCT TC4 ON T1.CHL_ID = TC4.FINPROD_ID
                   LEFT JOIN FIN_PRODUCT_TYPE FPROD_TYPE ON FPROD_TYPE.FINPROD_ID = T1.FINPROD_ID
                  WHERE T1.TRADE_STATUS = ''01''
                    AND NVL(T1.IS_OVERDUE_DEAL, ''N'') = ''N''
                    AND T1.IS_CANCEL = ''N''
                    AND T1.FINPROD_TYPE2 = ''F07''
                    AND T1.P_TOTLE_TRADE_ID IS NULL
                    AND T3.PA_BUSS_TYPE = ''41''
                    AND t1.trade_date=date''${valDate}''
                  GROUP BY  t1.portfolio_id
                  UNION ALL
SELECT
    VAL.PORTFOLIO_ID RKEY,NVL(SUM(NVL(VAL.MARKET_VALUE,0)+nvl(VAL.TDY_INTINCEXP, 0)),0) RVALUE
FROM PTL_SEC_PIERCE_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN PA_FIN_PRODUCT PFP ON PFP.FINPROD_ID = PRD.FINPROD_ID
WHERE VAL.CDATE = date''${valDate}'' - 1 AND PRD.FINPROD_TYPE2 = ''F07''
-- 这里是是否可提前支取的条件
AND PRD.MDATE IS NOT NULL AND FPT.TYPE_6 != ''D03''
GROUP BY VAL.PORTFOLIO_ID
 )GROUP BY rkey', 'portfolioCode', 'N', 'admin', '001', '12-9月 -20 07.40.53.161000 下午', 'admin', '12-9月 -20 07.40.53.397000 下午');

