        FROM BOK_VAL_TABLE_DATA
 WHERE 1=1  AND BOOKSET_ID IN (
 SELECT prod.finprod_id FROM fin_product prod WHERE prod.finprod_market_id=${portfolioCode})
   AND VAL_DATE = DATE ''${valDate}''-1
