 WHERE 1=1  AND BOOKSET_ID IN (
 SELECT prod.finprod_id FROM fin_product prod WHERE prod.finprod_market_id=${portfolioCode})
   AND VAL_DATE = DATE ''${valDate}''-1
   AND DETAIL_DIST IN ( ''05'',''06'')', 'portfolioCode', 'N', 'admin', '001', '10-9月 -20 04.31.48.555000 下午', 'admin', '10-9月 -20 04.31.48.833000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('JESHJE', '04', 'SQL', 'SELECT
---如果巨额赎回比例> 0 
 CASE
     WHEN (SELECT NVL(A.HUGE_RED_RATIO, 0)
             FROM PRD_SALE_PARAM A
            WHERE A.FINPROD_ID IN
                  (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})) > 0 THEN
      (
      ----如果赎回金额>0
      CASE
          WHEN (SELECT NVL(SUM(A.TRADE_AMT), 0) SHAREAMT
                  FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                 WHERE A.FINPROD_TYPE2 = ''''F16''''
                   AND A.PS = ''''C4''''
                   AND A.TRADE_DATE <= SYSDATE
                   AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                   AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                   AND A.TRADE_DATE = date''''${valDate}'''') > 0 THEN
           (
           ----如果巨额赎回比例 > 赎回比例 
           CASE
               WHEN (SELECT NVL((SELECT A.HUGE_RED_RATIO
                                  FROM PRD_SALE_PARAM A
                                 WHERE A.FINPROD_ID IN
                                       (SELECT PROD.FINPROD_ID
                                          FROM FIN_PRODUCT PROD
                                         WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})),
                                0) -
                            ((SELECT SUM(A.TRADE_AMT) SHAREAMT
                                FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                               WHERE A.FINPROD_TYPE2 = ''''F16''''
                                 AND A.PS = ''''C4''''
                                 AND A.TRADE_DATE <= SYSDATE
                                 AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD ', 'portfolioCode', 'N', 'admin', '001', '09-9月 -20 08.13.26.215000 下午', 'admin', '09-9月 -20 08.13.26.457000 下午');
---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                                 AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                                 AND A.TRADE_DATE = date''''${valDate}'''') /
                             ((SELECT SUM(AMATCHAMT) REAMINAMT
                                 FROM (SELECT NVL(SUM(POS.AMOUNT), 0) AMATCHAMT,
                                              ''''剩余金额'''' AFINPRODTYPE2
                                         FROM PTL_CASH_POSITION POS
                                         LEFT JOIN FIN_PRODUCT_ADD T5
                                           ON T5.PORTFOLIO_ID = POS.PORTFOLIO_ID
                                         LEFT JOIN STL_FIN_PRODUCT_ACCT PTL
                                           ON POS.ACCT_ID = PTL.ACCT_NO
                                          AND T5.FINPROD_ID = PTL.FINPROD_ID
                                        WHERE T5.PORTFOLIO_ID = ${portfolioCode}
                                          AND HODING_TYPE = ''''01''''
                                          AND PTL.ACCT_TYPE IN (''''A01'''', ''''A07'''')
                                          AND POS.CDATE = TO_DATE(''''${valDate}'''', ''''YYYY-MM-DD'''')
                                          AND POS.CCY = ''''CNY''''
                                       UNION ALL
                                       SELECT NVL(SUM(AMOUNT), 0) AMATCHAMT, ''''剩余金额'''' AFINPRODTYPE2
                                         FROM PTL_CASH_POSITION_FLOW
                                        WHERE CDATE = TO_DATE(''''${valDate}'''', ''''YYYY-MM-DD'''')
                                          AND HODING_TYPE = ''''03''''
                                          AND ACCT_ID IN
                                              (SELECT ACCT_NO
                                                 FROM PTL_CAPACCT_INFO
                                                WHERE PORTFOLIO_ID = ${portfolioCode}
                                                  AND ACCT_TYPE IN (''''A01'''', ''''A07''''))
                                          AND PORTFOLIO_ID = ${portfolioCode}
                                          AND CCY = ''''CNY'''')) +
                             (SELECT SUM(A.TRADE_AMT) SHAREAMT
                                 FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                                WHERE A.FINPROD_TYPE2 = ''''F16''''
                                  AND A.PS = ''''C4''''
                                  AND A.TRADE_DATE <= SYSDATE
                                  AND A.FINPROD_ID IN ((SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode}))
                                  AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                                  AND A.TRADE_DATE = date''''${valDate}'''')) * 100) AS SHAREPERCENT
                       FROM DUAL) <= 0 THEN
                (SELECT SUM(A.TRADE_AMT) SHAREAMT
                   FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                  WHERE A.FINPROD_TYPE2 = ''''F16''''
                    AND A.PS = ''''C4''''
                    AND A.TRADE_DATE <= SYSDATE
                    AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                    AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                    AND A.TRADE_DATE = date''''${valDate}'''')
               ELSE
                (0)
           END)
          ELSE
           (0)
      END)
     ELSE
      (0)
 END AS HugeShareAmt
  FROM DUAL ' where PARA_CODE = 'JESHJE' and PARA_GRANULARITY='04';

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('JESHJE', '05', 'SQL', 'SELECT
---如果巨额赎回比例> 0 
 CASE
     WHEN (SELECT NVL(A.HUGE_RED_RATIO, 0)
             FROM PRD_SALE_PARAM A
            WHERE A.FINPROD_ID IN
                  (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})) > 0 THEN
      (
      ----如果赎回金额>0
      CASE
          WHEN (SELECT NVL(SUM(A.TRADE_AMT), 0) SHAREAMT
                  FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                 WHERE A.FINPROD_TYPE2 = ''''F16''''
                   AND A.PS = ''''C4''''
                   AND A.TRADE_DATE <= SYSDATE
                   AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                   AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                   AND A.TRADE_DATE = date''''${valDate}'''') > 0 THEN
           (
           ----如果巨额赎回比例 > 赎回比例 
           CASE
               WHEN (SELECT NVL((SELECT A.HUGE_RED_RATIO
                                  FROM PRD_SALE_PARAM A
                                 WHERE A.FINPROD_ID IN
                                       (SELECT PROD.FINPROD_ID
                                          FROM FIN_PRODUCT PROD
                                         WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})),
                                0) -
                            ((SELECT SUM(A.TRADE_AMT) SHAREAMT
                                FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                               WHERE A.FINPROD_TYPE2 = ''''F16''''
                                 AND A.PS = ''''C4''''
                                 AND A.TRADE_DATE <= SYSDATE
                                 AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD ', 'portfolioCode', 'N', 'admin', '001', '09-9月 -20 08.13.26.215000 下午', 'admin', '09-9月 -20 08.13.26.461000 下午');
---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                                 AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                                 AND A.TRADE_DATE = date''''${valDate}'''') /
                             ((SELECT SUM(AMATCHAMT) REAMINAMT
                                 FROM (SELECT NVL(SUM(POS.AMOUNT), 0) AMATCHAMT,
                                              ''''剩余金额'''' AFINPRODTYPE2
                                         FROM PTL_CASH_POSITION POS
                                         LEFT JOIN FIN_PRODUCT_ADD T5
                                           ON T5.PORTFOLIO_ID = POS.PORTFOLIO_ID
                                         LEFT JOIN STL_FIN_PRODUCT_ACCT PTL
                                           ON POS.ACCT_ID = PTL.ACCT_NO
                                          AND T5.FINPROD_ID = PTL.FINPROD_ID
                                        WHERE T5.PORTFOLIO_ID = ${portfolioCode}
                                          AND HODING_TYPE = ''''01''''
                                          AND PTL.ACCT_TYPE IN (''''A01'''', ''''A07'''')
                                          AND POS.CDATE = TO_DATE(''''${valDate}'''', ''''YYYY-MM-DD'''')
                                          AND POS.CCY = ''''CNY''''
                                       UNION ALL
                                       SELECT NVL(SUM(AMOUNT), 0) AMATCHAMT, ''''剩余金额'''' AFINPRODTYPE2
                                         FROM PTL_CASH_POSITION_FLOW
                                        WHERE CDATE = TO_DATE(''''${valDate}'''', ''''YYYY-MM-DD'''')
                                          AND HODING_TYPE = ''''03''''
                                          AND ACCT_ID IN
                                              (SELECT ACCT_NO
                                                 FROM PTL_CAPACCT_INFO
                                                WHERE PORTFOLIO_ID = ${portfolioCode}
                                                  AND ACCT_TYPE IN (''''A01'''', ''''A07''''))
                                          AND PORTFOLIO_ID = ${portfolioCode}
                                          AND CCY = ''''CNY'''')) +
                             (SELECT SUM(A.TRADE_AMT) SHAREAMT
                                 FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                                WHERE A.FINPROD_TYPE2 = ''''F16''''
                                  AND A.PS = ''''C4''''
                                  AND A.TRADE_DATE <= SYSDATE
                                  AND A.FINPROD_ID IN ((SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode}))
                                  AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                                  AND A.TRADE_DATE = date''''${valDate}'''')) * 100) AS SHAREPERCENT
                       FROM DUAL) <= 0 THEN
                (SELECT SUM(A.TRADE_AMT) SHAREAMT
                   FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                  WHERE A.FINPROD_TYPE2 = ''''F16''''
                    AND A.PS = ''''C4''''
                    AND A.TRADE_DATE <= SYSDATE
                    AND A.FINPROD_ID IN (SELECT PROD.FINPROD_ID
                     FROM FIN_PRODUCT PROD
                    WHERE PROD.FINPROD_MARKET_ID = ${portfolioCode})
                    AND A.IS_CANCEL = DECODE(''''01'''', ''''03'''', ''''Y'''', ''''N'''')
                    AND A.TRADE_DATE = date''''${valDate}'''')
               ELSE
                (0)
           END)
          ELSE
           (0)
      END)
     ELSE
      (0)
 END AS HugeShareAmt
  FROM DUAL ' where PARA_CODE = 'JESHJE' and PARA_GRANULARITY='05';

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('ZCJZ', '01', 'SQL', 'SELECT nvl(sum(DECODE(detail_dist,''05'',market_value,''06'',market_value*-1)),0) AS rvalue, prod.finprod_market_id AS rkey
        FROM BOK_VAL_TABLE_DATA
        LEFT JOIN fin_product prod ON prod.finprod_id = BOOKSET_ID AND prod.finprod_type2=''F16''
 WHERE 1=1  
   AND VAL_DATE = date''${valDate}''-1
   AND DETAIL_DIST IN ( ''05'',''06'')
   GROUP BY finprod_market_id', 'portfolioCode', 'N', 'admin', '001', '10-9月 -20 04.31.48.555000 下午', 'admin', '10-9月 -20 04.31.48.826000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XYDJZAAYXDZQ', '03', 'SQL', 'select * from
(
SELECT D.finprod_id AS RKEY,A.GRADE_RESULT || ''||'' || C.ITEM_VALUE AS RVALUE
 from MST_BOND_CREDIT_RATING A JOIN
(select O_CODE,max(GRADE_DATE) GRADE_DATE
from MST_BOND_CREDIT_RATING  where O_TYPE = ''01'' GROUP BY O_CODE) B
ON A.O_CODE = B.O_CODE AND A.GRADE_DATE = B.GRADE_DATE AND A.O_TYPE = ''01''
LEFT JOIN FIN_PRODUCT D ON D.finprod_market_id = A.o_code
JOIN
SYS_DATADICT_LIST C ON C.DICT_CODE=''MAIN_GRADE_RESULT'' and A.GRADE_RESULT = C.ITEM_CODE
WHERE D.finprod_id not in (select B.FINPROD_ID from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_11
 where B.TYPE_11 IN  (''011'',''013'') AND C.dict_code = ''CUSTOM_ASSET_TYPE_FOUR''
UNION ALL
select B.FINPROD_ID from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_8
 where B.TYPE_8 IN  (''F10'') AND C.dict_code = ''FINPROD_TYPE''
UNION ALL
select T1.FINPROD_ID from FIN_PRODUCT T1
LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID
AND T3.EFF_DATE = T1.VDATE WHERE T3.INT_TYPE = ''02''
)

UNION ALL

select B.FINPROD_ID RKEY,B.TYPE_11 || ''||'' || C.ITEM_VALUE RVALUE from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_11
 where B.TYPE_11 IN  (''011'',''013'') AND C.dict_code = ''CUSTOM_ASSET_TYPE_FOUR''
UNION ALL
select B.FINPROD_ID RKEY, B.TYPE_8 || ''||'' || C.ITEM_VALUE RVALUE from FIN_PRODUCT_TYPE B
LEFT JOIN SYS_DATADICT_LIST C ON C.ITEM_CODE = B.TYPE_8
 where B.TYPE_8 IN  (''F10'') AND C.dict_code = ''FINPROD_TYPE''
UNION ALL
select T1.FINPROD_ID RKEY , ''fd02'' || ''||'' || ''浮动利率债券'' RVALUE from FIN_PRODUCT T1
LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID
AND T3.EFF_DATE = T1.VDATE WHERE T3.INT_TYPE = ''02'')', 'assetCode', 'N', 'admin', '001', '17-9月 -20 11.23.16.970000 上午', 'admin', '17-9月 -20 11.23.17.202000 上午');

