INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID
AND N.CDATE <= DATE ''${valDate}'' - 1
INNER JOIN FIN_PRODUCT_TYPE T3 ON N.FINPROD_ID = T3.FINPROD_ID
AND ((T3.TYPE_8 = ''F01'' AND (T3.TYPE_6 NOT IN (''B01'',''B03'',''B05'',''B14'',''B15'')
OR (T3.TYPE_6 = ''B05'' AND T3.TYPE_7 != ''01''))) OR T3.TYPE_8 NOT IN (''F01'',''F11''))
WHERE N.FINPROD_ID NOT IN (SELECT FINPROD_ID FROM FDLVBOND UNION ALL SELECT FINPROD_ID FROM AABOND)
AND M.CDATE = date''${valDate}'' - 1
GROUP BY M.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', '12-9月 -20 02.16.35.442000 下午', 'admin', '12-9月 -20 02.16.35.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('WGJYRDQJDQJTJRGJGZ', '04', 'SQL', 'WITH FDLVBOND AS (
    -- 浮动利率债券（未进入最后一个利率调整期）
    SELECT FCI.FINPROD_ID FROM FIN_CASH_CALC_RULE FCI
    INNER JOIN (
	    SELECT MAX(EFF_DATE) EFF_DATE, FINPROD_ID FROM FIN_CASH_CALC_RULE 
		WHERE CALC_TYPE = ''02'' GROUP BY FINPROD_ID
	) FCC
    ON FCC.FINPROD_ID = FCI.FINPROD_ID AND FCI.EFF_DATE = FCC.EFF_DATE
    WHERE FCI.CALC_TYPE = ''02'' AND FCI.EFF_DATE > DATE ''${valDate}''
),
AABOND AS (
    -- 信用等级在AA+以下的债券
    SELECT FP.FINPROD_ID FROM FIN_PRODUCT FP 
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID AND FPT.TYPE_8 = ''F01'' AND FPT.TYPE_6 != ''B13''
    LEFT JOIN MST_BOND_CREDIT_RATING RT ON RT.O_CODE = FP.FINPROD_MARKET_ID AND RT.O_TYPE = ''01''
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND RT.GRADE_RESULT NOT IN (''01'', ''02'', ''03'', ''04'') OR RT.GRADE_RESULT IS NULL
  UNION ALL
    -- 信用等级在AA+以下的资产支持证券
    SELECT FP.FINPROD_ID FROM FIN_PRODUCT FP 
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID AND FPT.TYPE_6 = ''B13''
    LEFT JOIN MST_BOND_CREDIT_RATING RT ON RT.O_CODE = FP.FINPROD_MARKET_ID AND RT.O_TYPE = ''02''
    WHERE FP.FINPROD_TYPE2 = ''F01'' AND RT.GRADE_RESULT NOT IN (''01'', ''02'', ''03'', ''04'') OR RT.GRADE_RESULT IS NULL
),
PROD AS (
    -- 资产到期向前第5个交易日
    SELECT FINPROD_ID, MDATE, CDATE FROM (
        SELECT FINPROD_ID, MDATE, CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE asc) RN FROM (
            SELECT m.FINPROD_ID, m.MDATE, MH.CDATE, ROW_NUMBER() OVER(PARTITION BY FINPROD_ID ORDER BY CDATE desc) ROWNO FROM (
                SELECT FPT.FINPROD_ID,FPT.MDATE,NVL(FPT.CALENDAR_ID,''01'') CALENDAR_ID FROM FIN_PRODUCT FPT
                WHERE FPT.MDATE IS NOT NULL AND FPT.MDATE >= DATE ''${valDate}'' - 1
            ) m
            INNER JOIN MST_HOLIDAY MH ON MH.CALENDAR_ID = m.CALENDAR_ID AND m.MDATE >= MH.CDATE  AND MH.IS_HOLIDAY = ''0''
        ) WHERE ROWNO <= 5
    ) WHERE RN = 1
) ', 'portfolioCode', 'N', 'admin', '001', '12-9月 -20 02.16.35.442000 下午', 'admin', '12-9月 -20 02.16.35.655000 下午');
---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' SELECT SUM(TRADE_AMT) RVALUE FROM (
    SELECT
        NVL(SUM(NVL(M.MARKET_VALUE ,0)),0) TRADE_AMT
    FROM PTL_SEC_PIERCE_VALUTION M
    INNER JOIN PROD N ON M.FINPROD_ID = N.FINPROD_ID
    AND N.CDATE <= DATE ''${valDate}''
    INNER JOIN FIN_PRODUCT_TYPE T3 ON N.FINPROD_ID = T3.FINPROD_ID
    AND ((T3.TYPE_8 = ''F01'' AND (T3.TYPE_6 NOT IN (''B01'',''B03'',''B05'',''B14'',''B15'')
    OR (T3.TYPE_6 = ''B05'' AND T3.TYPE_7 != ''01''))) OR T3.TYPE_8 NOT IN (''F01'',''F11''))
    WHERE N.FINPROD_ID NOT IN (SELECT FINPROD_ID FROM FDLVBOND UNION ALL SELECT FINPROD_ID FROM AABOND)
    AND M.CDATE = date''${valDate}'' - 1 AND  M.PORTFOLIO_ID IN ${portfolioCode}
  UNION ALL 
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)   
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
    - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT
    FROM TRD_PRODUCT_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID 
    AND t2.CDATE <= DATE ''${valDate}''
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0
    AND ((T3.TYPE_8 = ''F01'' AND (T3.TYPE_6 NOT IN (''B01'',''B03'',''B05'',''B14'',''B15'')
    OR (T3.TYPE_6 = ''B05'' AND T3.TYPE_7 != ''01''))) OR T3.TYPE_8 NOT IN (''F01'',''F11''))
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND t2.FINPROD_ID NOT IN (SELECT FINPROD_ID FROM FDLVBOND UNION ALL SELECT FINPROD_ID FROM AABOND)
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T38'', ''T39'') 
	' where PARA_CODE = 'WGJYRDQJDQJTJRGJGZ' and PARA_GRANULARITY='04';
  ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION ALL 
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)    
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) 
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)  AS TRADE_AMT
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID 
    AND t2.CDATE <= DATE ''${valDate}''
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0
    AND ((T3.TYPE_8 = ''F01'' AND (T3.TYPE_6 NOT IN (''B01'',''B03'',''B05'',''B14'',''B15'')
    OR (T3.TYPE_6 = ''B05'' AND T3.TYPE_7 != ''01''))) OR T3.TYPE_8 NOT IN (''F01'',''F11''))
    WHERE m.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND t2.FINPROD_ID NOT IN (SELECT FINPROD_ID FROM FDLVBOND UNION ALL SELECT FINPROD_ID FROM AABOND)
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'',''T52'')
  
  UNION ALL 
    SELECT
      nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)  AS TRADE_AMT
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
  INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN PROD t2 ON t2.FINPROD_ID = n.FINPROD_ID 
    AND t2.CDATE <= DATE ''${valDate}''
    INNER JOIN FIN_PRODUCT_TYPE t3 ON n.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH = 0
    AND ((T3.TYPE_8 = ''F01'' AND (T3.TYPE_6 NOT IN (''B01'',''B03'',''B05'',''B14'',''B15'')
    OR (T3.TYPE_6 = ''B05'' AND T3.TYPE_7 != ''01''))) OR T3.TYPE_8 NOT IN (''F01'',''F11''))
    WHERE n.counter_id IN ${portfolioCode} AND n.TRADE_DATE = DATE''${valDate}''
    AND t2.FINPROD_ID NOT IN (SELECT FINPROD_ID FROM FDLVBOND UNION ALL SELECT FINPROD_ID FROM AABOND)
    AND n.PS = ''T02''
    AND EXISTS (SELECT 1 FROM SYS_PARA WHERE PARA_CODE = ''is_auto_generate_negate_deal'' AND PARAM_VALUE = ''Y'')
)' where PARA_CODE = 'WGJYRDQJDQJTJRGJGZ' and PARA_GRANULARITY='04';

