insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('ZCSYCXQX', '02', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,TO_NUMBER(MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION
    --拆借交易
    SELECT FINPROD_ID,TO_NUMBER(MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F09'')
  UNION
    -- 活期存款
    SELECT FP.FINPROD_ID,0 LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F05'' AND FPT.TYPE_6 = ''D03''
  UNION
    -- 非活期存款
    SELECT FP.FINPROD_ID,TO_NUMBER(FP.MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F05'' AND FPT.TYPE_6 != ''D03''
  UNION
    -- 计划类净值型、计划类利率型
    SELECT FP.FINPROD_ID,1 LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 IN (''F04'',''F09'')
  UNION
    -- 基金
    SELECT FP.FINPROD_ID, DECODE(PLAN.MDATE, NULL, 1, TO_NUMBER(PLAN.MDATE - DATE ''${valDate}'')) LAST_PERIOD
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        -- 下一个开放赎回起始日
        SELECT min(FOP.OPEN_DATE_STR) MDATE, FOP.FINPROD_ID FROM FIN_OPEN_PLAN FOP
        INNER JOIN FIN_PRODUCT_TYPE FPT ON FOP.FINPROD_ID = FPT.FINPROD_ID
        WHERE OPEN_DATE_STR > DATE ''${valDate}'' AND FPT.TYPE_8 = ''F02''
        GROUP BY FOP.FINPROD_ID
    ) PLAN ON PLAN.FINPROD_ID = FP.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F02'' ', 'assetCode', 'N', 'admin', '001', '15-9月 -20 07.40.13.764000 下午', 'admin', '15-9月 -20 07.40.13.995000 下午');
  ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION
    -- 其他资产
    SELECT FP.FINPROD_ID,TO_NUMBER(FP.MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 NOT IN (''F02'',''F05'',''F04'',''F09'',''F19'')
)
SELECT NVL(SUM(NVL(LAST_PERIOD,0)*TRADE_AMT),0) RVALUE, portfolio_id rkey FROM (SELECT SUM(NVL(TRADE_AMT,0)) TRADE_AMT, FINPROD_ID RKEY, LAST_PERIOD,PORTFOLIO_ID FROM (
    SELECT SUM(NVL(PSP.Dsc_Cost_Amt,0) + NVL(TDY_INTINCEXP, 0)) TRADE_AMT, PSP.FINPROD_ID, ASSET.LAST_PERIOD,PSP.PORTFOLIO_ID
    FROM PTL_SEC_PIERCE_VALUTION PSP 
    INNER JOIN ASSET ON ASSET.FINPROD_ID = PSP.FINPROD_ID
    WHERE PSP.CDATE = DATE ''${valDate}''-1
    AND PSP.SUB_CODE IS NULL
    GROUP BY PSP.FINPROD_ID, ASSET.LAST_PERIOD,PORTFOLIO_ID
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T19'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T07'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T08'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T09'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T11'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T22'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T23'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T38'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T39'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT,
        n.FINPROD_ID, ASSET.LAST_PERIOD,m.PORTFOLIO_ID
    FROM TRD_PRODUCT_DEAL_ADD m
    INNER JOIN TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE n.TRADE_DATE = DATE''${valDate}'' AND m.PORTFOLIO_ID IN ''JRSJ0911''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T19'', ''T07'', ''T08'', ''T09'', ''T11'', ''T52'', ''T22'', ''T23'', ''T39'', ''T39'')
    GROUP BY n.FINPROD_ID, ASSET.LAST_PERIOD,m.PORTFOLIO_ID ' where PARA_CODE = 'ZCSYCXQX' and PARA_GRANULARITY='02';
    ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      - nvl(sum(decode(n.PS, ''T03'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)  AS TRADE_AMT,
      n.FINPROD_ID, ASSET.LAST_PERIOD,m.PORTFOLIO_ID
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE 
    n.TRADE_DATE = DATE''${valDate}''
    AND n.PS IN (''T01'', ''T02'', ''T03'', ''T04'', ''T52'')
    GROUP BY n.FINPROD_ID, ASSET.LAST_PERIOD,m.PORTFOLIO_ID
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T02'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0) AS TRADE_AMT, n.FINPROD_ID,
    ASSET.LAST_PERIOD,n.counter_id AS PORTFOLIO_ID
    FROM WFL_TRD_PRODUCT_DEAL_ADD m
    INNER JOIN WFL_TRD_PRODUCT_DEAL n ON m.TRADE_ID = n.TRADE_ID AND n.TRADE_STATUS != ''03''
    INNER JOIN SYS_WFL_BUSINESS_LIST swbl on n.WORKFLOW_ID = swbl.SEQ_NO and swbl.PROCESS_STATE != ''BACK''
    INNER JOIN ASSET ON ASSET.FINPROD_ID = n.FINPROD_ID
    WHERE 
     n.TRADE_DATE = DATE''${valDate}''
    AND n.PS =''T02''
    AND EXISTS (SELECT 1 FROM SYS_PARA WHERE PARA_CODE = ''is_auto_generate_negate_deal'' AND PARAM_VALUE = ''Y'')
    GROUP BY n.FINPROD_ID, ASSET.LAST_PERIOD,n.counter_id
) GROUP BY FINPROD_ID, LAST_PERIOD, PORTFOLIO_ID
) GROUP BY portfolio_id ' where PARA_CODE = 'ZCSYCXQX' and PARA_GRANULARITY='02';

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('ZCSYCXQX', '03', 'SQL', 'WITH ASSET AS (
    -- 逆回购交易
    SELECT FINPROD_ID,TO_NUMBER(MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F03'',''F05'')
  UNION
    --拆借交易
    SELECT FINPROD_ID,TO_NUMBER(MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_TRADE_PRODUCT
    WHERE FINPROD_TYPE2 IN (''F09'')
  UNION
    -- 活期存款
    SELECT FP.FINPROD_ID,0 LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F05'' AND FPT.TYPE_6 = ''D03''
  UNION
    -- 非活期存款
    SELECT FP.FINPROD_ID,TO_NUMBER(FP.MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F05'' AND FPT.TYPE_6 != ''D03''
  UNION
    -- 计划类净值型、计划类利率型
    SELECT FP.FINPROD_ID,1 LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 IN (''F04'',''F09'')
  UNION
    -- 基金
    SELECT FP.FINPROD_ID, DECODE(PLAN.MDATE, NULL, 1, TO_NUMBER(PLAN.MDATE - DATE ''${valDate}'')) LAST_PERIOD
    FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    LEFT JOIN (
        -- 下一个开放赎回起始日
        SELECT min(FOP.OPEN_DATE_STR) MDATE, FOP.FINPROD_ID FROM FIN_OPEN_PLAN FOP
        INNER JOIN FIN_PRODUCT_TYPE FPT ON FOP.FINPROD_ID = FPT.FINPROD_ID
        WHERE OPEN_DATE_STR > DATE ''${valDate}'' AND FPT.TYPE_8 = ''F02''
        GROUP BY FOP.FINPROD_ID
    ) PLAN ON PLAN.FINPROD_ID = FP.FINPROD_ID
    WHERE FPT.TYPE_8 = ''F02'' ', 'assetCode', 'N', 'admin', '001', '15-9月 -20 07.40.13.764000 下午', 'admin', '15-9月 -20 07.40.14.001000 下午');
  ---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' UNION
    -- 其他资产
    SELECT FP.FINPROD_ID,TO_NUMBER(FP.MDATE - DATE ''${valDate}'') LAST_PERIOD FROM FIN_PRODUCT FP
    INNER JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
    WHERE FPT.TYPE_8 NOT IN (''F02'',''F05'',''F04'',''F09'',''F19'')
)
SELECT NVL(SUM(NVL(LAST_PERIOD,0)*TRADE_AMT),0) RVALUE, portfolio_id rkey FROM (SELECT SUM(NVL(TRADE_AMT,0)) TRADE_AMT, FINPROD_ID RKEY, LAST_PERIOD,PORTFOLIO_ID FROM (
    SELECT SUM(NVL(PSP.Dsc_Cost_Amt,0) + NVL(TDY_INTINCEXP, 0)) TRADE_AMT, PSP.FINPROD_ID, ASSET.LAST_PERIOD,PSP.PORTFOLIO_ID
    FROM PTL_SEC_PIERCE_VALUTION PSP 
    INNER JOIN ASSET ON ASSET.FINPROD_ID = PSP.FINPROD_ID
    WHERE PSP.CDATE = DATE ''${valDate}''-1
    AND PSP.SUB_CODE IS NULL
    GROUP BY PSP.FINPROD_ID, ASSET.LAST_PERIOD,PORTFOLIO_ID
  UNION ALL
    SELECT
        nvl(sum(decode(n.PS, ''T01'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T04'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
      + nvl(sum(decode(n.PS, ''T52'', decode(TRADE_STATUS, ''03'', n.TRADE_AMT*-1, n.TRADE_AMT))), 0)
