values ('TZYDYZTXYPJDYAAAJGHJ', '03', 'SQL', 'SELECT
SUM(NVL(VAL.TDY_FLOAT_INGPL,0)+NVL(VAL.DSC_COST_AMT,0)+NVL(VAL.TDY_INTINCEXP,0)) RVALUE,
    VAL.PORTFOLIO_ID || '','' || PRD.ISSUER RKEY
FROM PTL_SEC_VALUTION VAL
INNER JOIN FIN_PRODUCT PRD ON VAL.FINPROD_ID = PRD.FINPROD_ID
INNER JOIN FIN_PRODUCT_TYPE TYP ON TYP.FINPROD_ID = PRD.FINPROD_ID AND TYP.TYPE_8 IN (''F01'', ''F05'')
INNER JOIN (
  select mbcr.O_CODE,max(mbcr.GRADE_RESULT) GRADE_RESULT from MST_BOND_CREDIT_RATING mbcr WHERE mbcr.o_type = ''01''
  AND mbcr.GRADE_RESULT NOT IN (''01'',''02'') GROUP BY mbcr.O_CODE
) D ON  D.O_CODE = PRD.finprod_market_id
 WHERE VAL.CDATE = date''${valDate}'' - 1
GROUP BY VAL.PORTFOLIO_ID,PRD.ISSUER', 'portfolioCode,issuerCode', 'N', 'admin', '001', '16-9月 -20 06.19.15.653000 下午', 'admin', '16-9月 -20 06.19.15.653000 下午');

insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('XJGLLCPSZFZCJZYTYCBPLD', '02', 'SQL', 'SELECT nvl(sum(SUBJECT_NAME),0)/100 AS rvalue,prod.finprod_market_id AS rkey
        FROM BOK_VAL_TABLE_DATA
        LEFT JOIN fin_product prod ON prod.finprod_id = BOOKSET_ID AND prod.finprod_type2=''F16''
 WHERE 1=1  
   AND VAL_DATE = date''${valDate}''-1
   AND DETAIL_DIST IN(''37'') GROUP BY prod.finprod_market_id', 'portfolioCode', 'N', 'admin', '001', '03-9月 -20 09.56.46.969000 下午', 'admin', '03-9月 -20 09.56.47.177000 下午');

