insert into RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME)
values ('JESHJE', '03', 'SQL', 'SELECT SUM(A.TRADE_AMT) AS rvalue,prod.finprod_market_id AS rkey FROM TRD_FIN_PRODUCT_DEAL_TOTAL A
                   LEFT JOIN FIN_PRODUCT prod ON a.finprod_id = prod.finprod_id
                  WHERE A.FINPROD_TYPE2 = ''F16'' AND A.PS = ''C4'' AND A.TRADE_DATE = date''2020-08-13''
                    AND A.IS_CANCEL = DECODE(''01'', ''03'', ''Y'', ''N'')
                    GROUP BY prod.finprod_market_id', 'portfolioCode', 'N', 'admin', '001', '09-9月 -20 08.13.26.215000 下午', 'admin', '09-9月 -20 08.13.26.451000 下午');

